import { WebSocketServer } from 'ws';
import { createHash } from 'crypto';
import { elliptic } from 'elliptic';

const ec = new elliptic.ec('secp256k1');

export function createAAPServer(port = 3000) {
  const wss = new WebSocketServer({ path: '/aap', port });
  const sessions = new Map();

  wss.on('connection', (ws) => {
    console.log('AAP: Client connected');

    ws.on('message', (data) => {
      try {
        const msg = JSON.parse(data);
        handleMessage(ws, msg);
      } catch (e) {
        ws.send(JSON.stringify({ error: 'Invalid JSON' }));
      }
    });

    ws.on('close', () => {
      console.log('AAP: Client disconnected');
    });
  });

  function handleMessage(ws, msg) {
    switch (msg.type) {
      case 'ready':
        handleReady(ws, msg);
        break;
      case 'answers':
        handleAnswers(ws, msg);
        break;
      default:
        ws.send(JSON.stringify({ error: 'Unknown type' }));
    }
  }

  function handleReady(ws, msg) {
    const nonce = createHash('sha256').update(Date.now().toString() + Math.random()).digest('hex').substring(0, 16);
    const session = {
      nonce,
      publicKey: msg.publicKey,
      challenges: generateChallenges()
    };
    sessions.set(ws, session);
    console.log('AAP: Client ready, sending challenges');
    ws.send(JSON.stringify({ type: 'challenges', nonce, challenges: session.challenges }));
  }

  function handleAnswers(ws, msg) {
    const session = sessions.get(ws);
    if (!session) {
      ws.send(JSON.stringify({ type: 'result', verified: false, error: 'No session' }));
      return;
    }

    const { answers, signature, timestamp, publicId } = msg;

    // Verify signature
    const proofData = JSON.stringify({ nonce: session.nonce, answers, publicId, timestamp });
    const isValid = verifySignature(session.publicKey, proofData, signature);

    // Verify answers
    let correct = 0;
    for (let i = 0; i < session.challenges.length; i++) {
      if (answers[i] === session.challenges[i].answer) correct++;
    }
    const allCorrect = correct === session.challenges.length;

    const verified = isValid && allCorrect;
    console.log(`AAP: Signature valid=${isValid}, Answers correct=${correct}/${session.challenges.length}`);

    ws.send(JSON.stringify({ 
      type: 'result', 
      verified, 
      sessionToken: createHash('sha256').update(Date.now().toString()).digest('hex'),
      correctCount: correct,
      totalChallenges: session.challenges.length
    }));

    sessions.delete(ws);
  }

  return wss;
}

function generateChallenges() {
  const challenges = [];
  for (let i = 0; i < 7; i++) {
    const ops = ['+', '-', '*'];
    const op = ops[i % 3];
    const a = Math.floor(Math.random() * 100);
    const b = Math.floor(Math.random() * 100);
    let answer;
    switch (op) {
      case '+': answer = a + b; break;
      case '-': answer = a - b; break;
      case '*': answer = a * b; break;
    }
    challenges.push({ id: i, question: `${a} ${op} ${b}`, answer });
  }
  return challenges;
}

function verifySignature(publicKey, data, signature) {
  try {
    const pubKey = ec.keyFromPublic(publicKey, 'hex');
    const sig = ec.keyFromPublic(signature, 'hex');
    return pubKey.verify(data, sig);
  } catch (e) {
    // Parse signature properly
    const r = BigInt('0x' + signature.substring(0, 64));
    const s = BigInt('0x' + signature.substring(64, 128));
    const pubKey = ec.keyFromPublic(publicKey, 'hex');
    return pubKey.verify(data, { r, s });
  }
}

export default createAAPServer;
