import { WebSocket } from 'ws';
import { createHash } from 'crypto';
import { elliptic } from 'elliptic';

const ec = new elliptic.ec('secp256k1');

export class AAPClient {
  constructor({ serverUrl, identity }) {
    this.serverUrl = serverUrl;
    this.identity = identity || this.generateDeterministicIdentity();
    this.ws = null;
  }

  generateDeterministicIdentity() {
    // Deterministic identity from marker
    const marker = 'AAP-DETERMINISTIC-MARKER-42';
    const seed = createHash('sha256').update(marker).digest();
    const keyPair = ec.keyFromPrivate(seed);
    return {
      privateKey: keyPair.getPrivate('hex'),
      publicKey: keyPair.getPublic('hex'),
      publicId: createHash('sha256').update(keyPair.getPublic('hex')).digest('hex').substring(0, 16)
    };
  }

  async verify() {
    return new Promise((resolve, reject) => {
      this.ws = new WebSocket(this.serverUrl);

      this.ws.on('open', () => {
        console.log('AAP Client: Connected, sending ready');
        this.ws.send(JSON.stringify({
          type: 'ready',
          publicKey: this.identity.publicKey
        }));
      });

      this.ws.on('message', (data) => {
        const msg = JSON.parse(data);
        console.log('AAP Client: Received', msg.type);

        if (msg.type === 'challenges') {
          this.handleChallenges(msg);
        } else if (msg.type === 'result') {
          console.log('AAP Client: Verification result:', msg);
          this.ws.close();
          resolve(msg);
        } else if (msg.error) {
          this.ws.close();
          reject(new Error(msg.error));
        }
      });

      this.ws.on('error', reject);
    });
  }

  handleChallenges(msg) {
    const { challenges, nonce } = msg;
    const answers = [];
    const proofPayload = {};

    for (const challenge of challenges) {
      // Parse and solve the challenge
      const parts = challenge.question.split(' ');
      const a = parseInt(parts[0]);
      const op = parts[1];
      const b = parseInt(parts[2]);
      let answer;
      switch (op) {
        case '+': answer = a + b; break;
        case '-': answer = a - b; break;
        case '*': answer = a * b; break;
        default: answer = 0;
      }
      answers.push(answer);
      proofPayload[challenge.id] = { question: challenge.question, answer };
    }

    const timestamp = Date.now();

    // Create proof data to sign
    const proofData = JSON.stringify({ nonce, answers, publicId: this.identity.publicId, timestamp });

    // Sign with secp256k1
    const keyPair = ec.keyFromPrivate(this.identity.privateKey);
    const sig = keyPair.sign(proofData);
    const signature = sig.toDER('hex');

    console.log('AAP Client: Sending answers with signature');
    console.log('AAP Client: Proof payload:', JSON.stringify(proofPayload, null, 2));

    this.ws.send(JSON.stringify({
      type: 'answers',
      answers,
      signature,
      timestamp,
      publicId: this.identity.publicId,
      proofPayload
    }));
  }
}

export function generateDeterministicIdentity(marker = 'AAP-DETERMINISTIC-MARKER-42') {
  const seed = createHash('sha256').update(marker).digest();
  const keyPair = ec.keyFromPrivate(seed);
  return {
    privateKey: keyPair.getPrivate('hex'),
    publicKey: keyPair.getPublic('hex'),
    publicId: createHash('sha256').update(keyPair.getPublic('hex')).digest('hex').substring(0, 16)
  };
}

export default AAPClient;
