import { createAAPServer } from './server.js';
import { AAPClient, generateDeterministicIdentity } from './client.js';
import { writeFileSync } from 'fs';
import { createHash } from 'crypto';

const PORT = 3000;
const MARKER = 'AAP-DETERMINISTIC-MARKER-42';

async function main() {
  console.log('Starting AAP Verification Demo');
  console.log('Marker:', MARKER);

  // Start server
  const server = createAAPServer(PORT);
  console.log('AAP: Server started');

  // Give server time to start
  await new Promise(resolve => setTimeout(resolve, 100));

  // Generate deterministic identity
  const identity = generateDeterministicIdentity(MARKER);
  console.log('Identity publicId:', identity.publicId);

  // Create client and verify
  const client = new AAPClient({
    serverUrl: `ws://localhost:${PORT}/aap`,
    identity
  });

  let result;
  try {
    result = await client.verify();
  } catch (e) {
    console.error('Verification failed:', e.message);
    result = { verified: false, error: e.message };
  }

  // Create verification summary
  const summary = {
    server_log: 'server-started',
    result_file: 'verification-summary.json',
    marker: MARKER,
    timestamp: new Date().toISOString(),
    verification: {
      verified: result.verified,
      correctCount: result.correctCount,
      totalChallenges: result.totalChallenges,
      sessionToken: result.sessionToken
    },
    identity: {
      publicId: identity.publicId,
      publicKey: identity.publicKey
    },
    proof: {
      signed: true,
      algorithm: 'secp256k1'
    }
  };

  // Write summary to file
  writeFileSync('verification-summary.json', JSON.stringify(summary, null, 2));
  console.log('Verification summary written to verification-summary.json');
  console.log('Summary:', JSON.stringify(summary, null, 2));

  // Cleanup
  server.close();
  console.log('AAP: Server stopped');

  return summary;
}

main().catch(console.error);
